#include <algorithm>
#include <cstdint>
#include <map>
#include <stdexcept>
#include <string>
#include <vector>

enum class OpKind { Read, Write };
struct Op { OpKind kind; std::uint32_t id; std::uint64_t offset; std::uint32_t length; std::string data; };
struct Completion { std::uint32_t id; std::uint32_t error; std::string data; };

constexpr std::uint32_t ERROR_HANDLE_EOF = 38, ERROR_OPERATION_ABORTED = 995;

class CopyEngine
{
public:
    CopyEngine(std::uint64_t fileSize, std::uint32_t chunkSize, int maxOutstanding)
        : size_{ fileSize }, chunk_{ chunkSize }, limit_{ maxOutstanding }
    {
    }

    std::vector<Op> start()
    {
        std::vector<Op> ops;
        fillReads(ops);
        return ops;
    }

    std::vector<Op> onCompletion(const Completion& c)
    {
        const auto it{ inFlight_.find(c.id) };
        if (it == inFlight_.end()) throw std::invalid_argument("no such operation in flight");
        const Op op{ it->second };
        inFlight_.erase(it);
        std::vector<Op> ops;

        if (c.error != 0)
        {
            if (!(cancelled_ && c.error == ERROR_OPERATION_ABORTED)) fail(c.error);
            return ops;
        }
        if (failed_ || cancelled_) return ops;

        if (op.kind == OpKind::Read)
        {
            if (c.data.size() != op.length)
            {
                fail(ERROR_HANDLE_EOF);
                return ops;
            }
            ops.push_back(issue(OpKind::Write, op.offset, static_cast<std::uint32_t>(c.data.size()), c.data));
        }
        else
        {
            written_ += op.length;
            fillReads(ops);
        }
        return ops;
    }

    std::vector<std::uint32_t> cancel()
    {
        cancelled_ = true;
        std::vector<std::uint32_t> ids;
        for (const auto& [id, op] : inFlight_) ids.push_back(id);
        return ids;
    }

    bool finished() const { return !failed_ && !cancelled_ && written_ == size_ && inFlight_.empty(); }
    bool failed() const { return failed_; }
    bool cancelled() const { return cancelled_; }
    std::uint32_t error() const { return error_; }
    std::uint64_t bytesWritten() const { return written_; }
    int outstanding() const { return static_cast<int>(inFlight_.size()); }

private:
    Op issue(OpKind kind, std::uint64_t offset, std::uint32_t length, std::string data)
    {
        Op op{ kind, nextId_++, offset, length, std::move(data) };
        inFlight_.emplace(op.id, Op{ op.kind, op.id, op.offset, op.length, {} });
        return op;
    }

    void fillReads(std::vector<Op>& ops)
    {
        while (!failed_ && !cancelled_ && nextOffset_ < size_ && static_cast<int>(inFlight_.size()) < limit_)
        {
            const auto length{ static_cast<std::uint32_t>(std::min<std::uint64_t>(chunk_, size_ - nextOffset_)) };
            ops.push_back(issue(OpKind::Read, nextOffset_, length, {}));
            nextOffset_ += length;
        }
    }

    void fail(std::uint32_t code)
    {
        if (!failed_)
        {
            failed_ = true;
            error_ = code;
        }
    }

    std::uint64_t size_;
    std::uint32_t chunk_;
    int limit_;
    std::uint64_t nextOffset_{ 0 };
    std::uint64_t written_{ 0 };
    std::uint32_t nextId_{ 1 };
    std::map<std::uint32_t, Op> inFlight_;
    bool failed_{ false };
    bool cancelled_{ false };
    std::uint32_t error_{ 0 };
};

unitTests:
#include <algorithm>
#include <deque>

struct Device {
    std::string source;
    std::string dest;
    std::vector<Op> pending;
    int maxInFlight{ 0 };
    std::uint32_t failId{ 0 };
    std::uint32_t failCode{ 0 };
    bool shrink{ false };
    explicit Device(std::string s) : source(std::move(s)), dest(source.size(), '?') {}
    void take(const std::vector<Op>& ops) {
        pending.insert(pending.end(), ops.begin(), ops.end());
        maxInFlight = std::max(maxInFlight, static_cast<int>(pending.size()));
    }
    Completion complete(std::size_t index) {
        Op op = pending[index];
        pending.erase(pending.begin() + static_cast<std::ptrdiff_t>(index));
        if (op.id == failId) return { op.id, failCode, {} };
        if (op.kind == OpKind::Read) {
            std::string data = source.substr(static_cast<std::size_t>(op.offset), op.length);
            if (shrink && op.offset > 0) data.pop_back();
            return { op.id, 0, data };
        }
        dest.replace(static_cast<std::size_t>(op.offset), op.data.size(), op.data);
        return { op.id, 0, {} };
    }
};

std::string text(std::size_t n) {
    std::string s;
    for (std::size_t i = 0; i < n; ++i) s += static_cast<char>('a' + (i * 7) % 26);
    return s;
}

void run(CopyEngine& e, Device& d, int pattern) {
    d.take(e.start());
    int step = 0;
    while (!d.pending.empty()) {
        std::size_t index = 0;
        if (pattern == 1) index = d.pending.size() - 1;
        if (pattern == 2) index = static_cast<std::size_t>(step * 5 + 3) % d.pending.size();
        d.take(e.onCompletion(d.complete(index)));
        ++step;
    }
}

TEST("copying in any completion order") {
    for (int pattern = 0; pattern < 3; ++pattern) {
        Device d(text(1000));
        CopyEngine e(1000, 64, 4);
        run(e, d, pattern);
        CHECK(d.dest == d.source);
        CHECK(e.finished());
        CHECK_EQ(e.bytesWritten(), 1000u);
        CHECK_EQ(e.outstanding(), 0);
        CHECK(d.maxInFlight <= 4);
    }
}
TEST("the first reads and the pipeline") {
    CopyEngine e(300, 100, 2);
    std::vector<Op> first = e.start();
    CHECK_EQ(first.size(), 2u);
    CHECK(first[0].kind == OpKind::Read && first[0].id == 1 && first[0].offset == 0 && first[0].length == 100);
    CHECK(first[1].id == 2 && first[1].offset == 100);
    std::vector<Op> next = e.onCompletion({ 2, 0, std::string(100, 'b') });
    CHECK_EQ(next.size(), 1u);
    CHECK(next[0].kind == OpKind::Write && next[0].id == 3 && next[0].offset == 100 && next[0].data == std::string(100, 'b'));
    next = e.onCompletion({ 3, 0, {} });
    CHECK_EQ(next.size(), 1u);
    CHECK(next[0].kind == OpKind::Read && next[0].offset == 200 && next[0].length == 100);
    CHECK_EQ(e.outstanding(), 2);
    CHECK_EQ(e.bytesWritten(), 100u);
}
TEST("the last chunk and tiny files") {
    CopyEngine e(250, 100, 8);
    std::vector<Op> ops = e.start();
    CHECK_EQ(ops.size(), 3u);
    CHECK(ops[2].offset == 200 && ops[2].length == 50);
    CopyEngine empty(0, 100, 4);
    CHECK(empty.start().empty());
    CHECK(empty.finished());
    Device d(text(5));
    CopyEngine small(5, 4096, 3);
    run(small, d, 0);
    CHECK(d.dest == d.source && small.finished());
}
TEST("errors fail the copy") {
    Device d(text(500));
    d.failId = 4;
    d.failCode = 112;
    CopyEngine e(500, 50, 3);
    run(e, d, 0);
    CHECK(e.failed() && !e.finished());
    CHECK_EQ(e.error(), 112u);
    CHECK_EQ(e.outstanding(), 0);
    CHECK(e.bytesWritten() < 500u);
}
TEST("a file that changed size") {
    Device d(text(400));
    d.shrink = true;
    CopyEngine e(400, 100, 2);
    run(e, d, 0);
    CHECK(e.failed());
    CHECK_EQ(e.error(), ERROR_HANDLE_EOF);
}
TEST("cancelling") {
    Device d(text(1000));
    CopyEngine e(1000, 100, 3);
    d.take(e.start());
    d.take(e.onCompletion(d.complete(0)));
    std::vector<std::uint32_t> ids = e.cancel();
    CHECK(ids == (std::vector<std::uint32_t>{ 2, 3, 4 }));
    CHECK(e.cancelled());
    CHECK(e.onCompletion({ 2, ERROR_OPERATION_ABORTED, {} }).empty());
    CHECK(e.onCompletion({ 3, 0, std::string(100, 'x') }).empty());
    CHECK(e.onCompletion({ 4, ERROR_OPERATION_ABORTED, {} }).empty());
    CHECK(!e.failed() && !e.finished());
    CHECK_EQ(e.outstanding(), 0);
    CHECK_THROWS_AS(e.onCompletion({ 4, 0, {} }), std::invalid_argument);
}

